/**
 * Generated by a real calibration and pitch tracker in `olb-vision`. Until
 * that repository exists, the viewer replays a synthetic trajectory so the
 * rendering path can be exercised end to end. Coordinates follow the
 * contract: origin at the rear apex of home plate, +x toward first base,
 * +y toward center field, +z up, metres.
 */
export interface PitchSample {
  /** Seconds from release. */
  t: number;
  p: [number, number, number];
}

export interface SyntheticPitch {
  samples: PitchSample[];
  /** Release speed, km/h. */
  speedKph: number;
  /** Horizontal movement from release to plate, cm. */
  breakCm: number;
  /** Flight time, seconds. */
  flightSeconds: number;
  synthetic: true;
}

const RELEASE_Y = 18.0;
const RELEASE_Z = 1.78;

function targetFor(call: string): [number, number] {
  switch (call) {
    case "B":
      return [0.62, 0.52];
    case "C":
    case "S":
    case "T":
      return [0.02, 0.86];
    case "F":
      return [0.3, 1.02];
    default:
      return [-0.08, 0.8];
  }
}

export function buildPitch(call: string): SyntheticPitch {
  const [targetX, targetZ] = targetFor(call);
  const releaseX = -0.42;
  const speedKph = call === "B" ? 128 : 142;
  const flightSeconds = (RELEASE_Y / (speedKph / 3.6));
  const samples: PitchSample[] = [];

  const count = 32;
  for (let i = 0; i < count; i += 1) {
    const u = i / (count - 1);
    const x = releaseX + (targetX - releaseX) * u;
    const y = RELEASE_Y * (1 - u);
    // Gravity plus a small arm-side run, both exaggerated for readability.
    const z = RELEASE_Z + (targetZ - RELEASE_Z) * u - 0.16 * u * u;
    samples.push({ t: Number((u * flightSeconds).toFixed(4)), p: [x, y, z] });
  }

  return {
    samples,
    speedKph,
    breakCm: Math.round(Math.abs(targetX - releaseX) * 100),
    flightSeconds,
    synthetic: true,
  };
}
